declare(strict_types=1);
$pageTitle='NPC Biographies';$topNavSection='configuration';$BODY_CLASS='hub-page';require dirname(__DIR__).'/ui_bootstrap.php';$rows=$uiRepository->rows('npc_biographies');$embedded=($_GET['embed']??'')==='1';include dirname(__DIR__).'/tmpl/head.html';if(!$embedded)include dirname(__DIR__).'/tmpl/navbar.php';
