<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>NPC Biography Management</h1><p>Focused biography editing for existing OpenMW NPC profiles. Other identity, routing, and inheritance fields are preserved.</p></div><span class="almsivi-badge"><?php echo count($rows); ?> NPCs</span></header><?php if(isset($_GET['status'])): ?><div class="almsivi-status">Biography saved.</div><?php endif; ?>
<section class="almsivi-grid"><?php foreach($rows as$row):$content=is_array($row['content'])?$row['content']:[];$identity=is_array($row['actor_identity'])?$row['actor_identity']:[]; ?><article class="almsivi-card"><div class="almsivi-card-header"><div><h2><?php echo almsivi_ui_h($row['name']); ?></h2><p class="almsivi-muted"><?php echo almsivi_ui_h($identity['record_id']??'Unknown record'); ?> · <?php echo almsivi_ui_h($identity['content_file']??'Morrowind.esm'); ?></p></div><span class="almsivi-badge">Revision <?php echo almsivi_ui_h($row['current_revision']); ?></span></div><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/profile-biography-revise"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="profile_id" value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><input type="hidden" name="base_content_json" value="<?php echo almsivi_ui_h(json_encode($content,JSON_UNESCAPED_SLASHES)); ?>"><label>Biography<textarea name="biography"><?php echo almsivi_ui_h($content['biography']??''); ?></textarea></label><label>Revision note<input name="change_reason" required value="Management biography update"></label><div class="almsivi-actions"><button type="submit">Save Biography</button></div></form></article><?php endforeach; ?><?php if($rows===[]): ?><article class="almsivi-card almsivi-empty">No NPC profiles exist yet.</article><?php endif; ?></section></main><?php include dirname(__DIR__).'/tmpl/footer.html'; ?>
